document.addEventListener('DOMContentLoaded',()=>{const s=document.querySelector('#interest'),l=document.querySelector('#finder-link');if(s&&l)s.addEventListener('change',()=>{l.href='/'+s.value+'/';});const inputs=[...document.querySelectorAll('.checklist input')],o=document.querySelector('#check-status');for(const c of inputs)c.addEventListener('change',()=>{o.textContent=inputs.filter(x=>x.checked).length+' / 5 項目を確認';});});